#include "GuestTextureFrameDiagnostic.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
static unsigned checks;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"texture frame diagnostic line%u: %s\n",__LINE__,#x);exit(1);}}while(0)
static int yes(void*x){(void)x;return 1;}
static void success(const SatchelGuestTextureFrameDiagnostic*r){CHECK(r->status==SATCHEL_GUEST_TFD_OK&&r->stage==10);CHECK(r->transfers_submitted==1&&r->transfer_finishes==1);CHECK(r->snapshots_started==2&&r->uploads_completed==2&&r->snapshots_completed==1);CHECK(r->pre_submit_cancellations==1&&r->pending_cancellations==1&&r->cancelled_snapshots_drained==1);CHECK(r->width==31&&r->height==17&&r->row_stride==124);CHECK(r->values_matched&&r->guards_matched&&r->cpu_mirror_unchanged&&r->state_preserved);CHECK(r->parent_protected&&r->texture_finalized&&r->device_finalized&&r->cpu_destroyed&&r->cpu_free_lease);CHECK(r->cleanup_matched&&!r->resources_retained&&!memcmp(&r->baseline,&r->final,sizeof(r->baseline)));CHECK(r->instructions>0&&r->dispatch_events>0);}
static void clean(void){SatchelGuestTextureFrameDiagnostic r;for(unsigned i=0;i<500;i++){uint32_t s=satchel_guest_texture_frame_diagnostic(&r,yes,NULL);CHECK(s==SATCHEL_GUEST_TFD_BUSY||s==SATCHEL_GUEST_TFD_CANCELLED);if(!r.resources_retained){CHECK(r.cleanup_matched);return;}struct timespec t={0,1000000};nanosleep(&t,NULL);}CHECK(0);}
static int reenter(void*x){unsigned*n=x;if(!(*n)++){SatchelGuestTextureFrameDiagnostic out,before;memset(&out,0x9a,sizeof(out));before=out;CHECK(satchel_guest_texture_frame_diagnostic(&out,NULL,NULL)==SATCHEL_GUEST_TFD_BUSY&&!memcmp(&out,&before,sizeof(out)));}return 0;}
typedef struct{unsigned count,at;} Cancel;
static int cancel_at(void*x){Cancel*c=x;return ++c->count>=c->at;}
int main(void){SatchelGuestTextureFrameDiagnostic out,before;memset(&out,0x95,sizeof(out));before=out;CHECK(satchel_guest_texture_frame_diagnostic(NULL,NULL,NULL)==SATCHEL_GUEST_TFD_INVALID);_Alignas(8)uint8_t unaligned[sizeof(out)+8];memset(unaligned,0xa5,sizeof(unaligned));CHECK(satchel_guest_texture_frame_diagnostic((void*)(unaligned+4),NULL,NULL)==SATCHEL_GUEST_TFD_INVALID);for(unsigned i=0;i<sizeof(unaligned);i++)CHECK(unaligned[i]==0xa5);CHECK(satchel_guest_texture_frame_diagnostic(&out,yes,NULL)==SATCHEL_GUEST_TFD_CANCELLED&&out.cleanup_matched&&!out.instructions&&!out.cpu_destroyed);unsigned n=0;uint32_t s=satchel_guest_texture_frame_diagnostic(&out,reenter,&n);if(s!=SATCHEL_GUEST_TFD_OK)fprintf(stderr,"status%u stage%u frame%u dispatch%u retired%u\n",s,out.stage,out.frame_status,out.dispatch_status,out.retirement_status);CHECK(s==SATCHEL_GUEST_TFD_OK);success(&out);printf("Original texture frame: %llu instructions/%llu dispatch events, snapshots%u/cancelled-drained%u.\n",(unsigned long long)out.instructions,(unsigned long long)out.dispatch_events,out.snapshots_completed,out.cancelled_snapshots_drained);for(unsigned at=2;at<=10;at+=2){Cancel c={0,at};s=satchel_guest_texture_frame_diagnostic(&out,cancel_at,&c);CHECK(s==SATCHEL_GUEST_TFD_CANCELLED);clean();}CHECK(satchel_guest_texture_frame_diagnostic(&out,NULL,NULL)==SATCHEL_GUEST_TFD_OK);success(&out);(void)before;printf("Texture frame diagnostic: %u host assertions (includes output-canary bytes).\n",checks);return 0;}
